using System;using System.Reflection;using System.Runtime.Serialization;
class DumpLoader {
 static void Main(string[] a){var asm=Assembly.LoadFrom(a[0]);var t=asm.GetType("AssetBundleDefine");var versions=(string[])t.GetField("VersionDir",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).GetValue(null);foreach(var x in (Array)t.GetField("m_EnemyBundles").GetValue(null)){var k=x.GetType();int v=Convert.ToInt32(k.GetProperty("version").GetValue(x,null));Console.WriteLine("B\t"+k.GetProperty("fileName").GetValue(x,null)+"\t"+v+"\tAndroid/"+versions[v]);}var loader=asm.GetType("AssetBundleLoader");foreach(string n in (string[])loader.GetField("ms_LocalAssetNameList",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).GetValue(null))Console.WriteLine("L\t"+n);var e=asm.GetType("EnemyData");var obj=FormatterServices.GetUninitializedObject(e);for(int i=0;i<100;i++){e.GetField("Type").SetValue(obj,i);if((bool)e.GetMethod("IsUnitEnemy").Invoke(obj,null))Console.WriteLine("U\t"+i);}var mt=asm.GetType("MotionData");var motions=(string[])mt.GetField("motionFilename").GetValue(null);for(int j=0;j<motions.Length;j++)Console.WriteLine("M\t"+j+"\t"+motions[j]);var aa=(int[,])asm.GetType("MotionAssign").GetField("ActionAssign").GetValue(null);for(int r=0;r<aa.GetLength(0);r++)for(int c=0;c<aa.GetLength(1);c++)Console.WriteLine("A\t"+r+"\t"+c+"\t"+aa[r,c]);var convert=asm.GetType("ConvertServerToClient").GetMethod("ConvertKindToCategory");for(int j=0;j<100;j++)Console.WriteLine("C\t"+j+"\t"+Convert.ToInt32(convert.Invoke(null,new object[]{j})));int ei=0;foreach(var eff in (Array)asm.GetType("EnemyAttackEffectAssign").GetField("m_DataList").GetValue(null)){foreach(var field in eff.GetType().GetFields())if(field.FieldType==typeof(string))Console.WriteLine("E\t"+ei+"\t"+field.Name+"\t"+field.GetValue(eff));ei++;}var basic=(Array)t.GetField("m_BasicBundles").GetValue(null);foreach(var b in basic){var bt=b.GetType();int v=Convert.ToInt32(bt.GetProperty("version").GetValue(b,null));Console.WriteLine("G\t"+bt.GetProperty("fileName").GetValue(b,null)+"\t"+v+"\tAndroid/"+versions[v]);}}
}
